  "assessment": {
    "kind": "configuration",
    "necessary": true,
    "established": true,
    "requirement": "The XInclude-context operation must be able to deliver XInclude and delegated parser or XPointer errors to a context-local structured callback with its supplied data.",
    "target_route": "The OLD entry reads a main XML entity, parses it, creates an xmlXIncludeCtxt, sets flags and calls xmlXIncludeProcessNode. A finite well-formed document containing xi:include with an invalid parse value reaches xmlXIncludeErr. The changed setter can install the structured callback on that same context, and included-document parsing and XPointer evaluation conditionally forward it.",
    "failure_condition": "The OLD entry never calls xmlXIncludeSetErrorHandler. xmlXIncludeNewContext zero-initializes errorHandler and errorCtxt, leaving the context-local structured route unreachable for every input.",
    "alternative_paths": "Input bytes only determine options and entities, not the private callback fields. The initializer installs a generic variadic error function, whose signature and registration differ from a context-local structured callback. The included-parser and XPointer forwarding paths both require the same non-NULL context callback, so they provide no equivalent route.",
    "source_evidence": [
      {"unit_id":"u-300d517982bdd0763602","start_line":2,"end_line":5,"role":"primary","dependency_reason":""},
      {"unit_id":"u-351dfd3246e4ba0d2e6f","start_line":10,"end_line":17,"role":"primary","dependency_reason":""},
      {"unit_id":"u-3b1bc4348a202c137e57","start_line":105,"end_line":109,"role":"dependency","dependency_reason":"Defines the context-local callback and data fields."},
      {"unit_id":"u-c9c14c015ed5688815f9","start_line":287,"end_line":298,"role":"dependency","dependency_reason":"Zero-initializes those fields when the context is created."},
      {"unit_id":"u-9b18b74e7400510fec7e","start_line":155,"end_line":161,"role":"dependency","dependency_reason":"XInclude errors forward those fields."},
      {"unit_id":"u-e7e92c8bc0bcd15133f2","start_line":406,"end_line":412,"role":"dependency","dependency_reason":"Included-document parsing forwards the configured handler."},
      {"unit_id":"u-64c179034730b0489dcd","start_line":1432,"end_line":1445,"role":"dependency","dependency_reason":"XPointer evaluation forwards the configured handler."},
      {"unit_id":"u-5c8cc6047a62e62bbb20","start_line":352,"end_line":369,"role":"dependency","dependency_reason":"An input-controlled invalid parse value produces an XInclude error."}
    ],
    "harness_evidence": [
      {"unit_id":"u-19cd550c9faddbff1f06","start_line":15,"end_line":25,"role":"dependency","dependency_reason":"The initializer registers only a generic error function."},
      {"unit_id":"u-57dccbae6481506c7233","start_line":49,"end_line":57,"role":"dependency","dependency_reason":"The registered generic function is variadic and does not have the structured callback signature."},
      {"unit_id":"u-19cd550c9faddbff1f06","start_line":37,"end_line":46,"role":"dependency","dependency_reason":"Input bytes control options and the main entity."},
      {"unit_id":"u-19cd550c9faddbff1f06","start_line":60,"end_line":69,"role":"primary","dependency_reason":"The complete context-use sequence omits the structured-handler setter."}
    ],
